# ProcessStartInfo.ArgumentList requires PowerShell 7; Windows PowerShell 5.1 has no
# ArgumentList and otherwise fails before starting a benchmark child process.
#requires -Version 7.0
param(
    [ValidateSet('exploration','confirmation')][string]$Batch='exploration',
    [Parameter(Mandatory)][ValidateRange(1,8)][int]$Block
)

$ErrorActionPreference = 'Stop'
$root = $PSScriptRoot
$inputPath = Join-Path (Resolve-Path (Join-Path $root '../../..')).Path 'Kotowari.Benchmarks/Data/test.json'
$expectedInputHash = 'DC87DD0FB85CB6F875AC336B70FEFC1E32BB1F284C8F6E011E0CB0256F9A354D'
if ((Get-FileHash -LiteralPath $inputPath -Algorithm SHA256).Hash -ne $expectedInputHash) { throw 'Input hash mismatch.' }

$cases = if ($Block % 2 -eq 1) { @('baseline','candidate') } else { @('candidate','baseline') }
foreach ($variant in $cases) {
    $runName = '{0:d2}-{1}' -f $Block,$variant
    $runRoot = Join-Path $root "runs/$Batch/$runName"
    $summaryPath = Join-Path $runRoot 'run-summary.json'
    if (Test-Path -LiteralPath $summaryPath) {
        $existingSummary = Get-Content -Raw -LiteralPath $summaryPath | ConvertFrom-Json
        if ($existingSummary.Run -ne $runName -or $existingSummary.Batch -ne $Batch -or $existingSummary.InputSHA256 -ne $expectedInputHash -or $existingSummary.ResultCount -ne 8) { throw "Existing run summary is invalid: $runName" }
        Write-Output "Preserving already completed $runName."
        continue
    }
    $reuseOutput = Test-Path -LiteralPath $runRoot
    $hostLog = Join-Path $runRoot 'host.log'
    $stderrPath = Join-Path $runRoot 'stderr.log'
    if ($reuseOutput) {
        if (-not (Test-Path -LiteralPath $hostLog) -or -not (Test-Path -LiteralPath $stderrPath)) { throw "Run output already exists and cannot be resumed: $runName" }
    } else {
        New-Item -ItemType Directory -Path $runRoot -Force | Out-Null
    }

    $manualRoot = Join-Path $root "$variant/host"
    $assembly = Join-Path $manualRoot 'StringExecutionRecovery.ChildHarness.dll'
    $measurementHost = Join-Path $manualRoot 'StringExecutionRecovery.Measurement.dll'
    $sourceRoot = Join-Path $root "$variant/source"
    if (-not (Test-Path -LiteralPath $assembly) -or -not (Test-Path -LiteralPath $measurementHost)) { throw "Frozen harness is not built: $assembly" }
    $manifestPath = Join-Path $root 'dll-manifest.json'
    if (-not (Test-Path -LiteralPath $manifestPath)) { throw 'Frozen DLL manifest is missing.' }
    $dllManifest = Get-Content -Raw -LiteralPath $manifestPath | ConvertFrom-Json
    $expectedDlls = @($dllManifest.$variant)
    foreach ($expectedDll in $expectedDlls) {
        $dllPath = Join-Path $manualRoot $expectedDll.Name
        if (-not (Test-Path -LiteralPath $dllPath) -or (Get-FileHash -LiteralPath $dllPath -Algorithm SHA256).Hash -ne $expectedDll.SHA256) { throw "Frozen DLL hash mismatch before run: $variant/$($expectedDll.Name)" }
    }

    $beforeHash = (Get-FileHash -LiteralPath $assembly -Algorithm SHA256).Hash
    if ($reuseOutput) {
        Write-Output "Validating existing completed process output for $runName."
        $stdout = Get-Content -Raw -LiteralPath $hostLog
        $stderr = if ((Get-Item -LiteralPath $stderrPath).Length -gt 0) { Get-Content -Raw -LiteralPath $stderrPath } else { '' }
        $processId = $null
        $utc = (Get-Item -LiteralPath $hostLog).CreationTimeUtc
        $elapsedSeconds = $null
        $affinity = 4
    } else {
        Write-Output "Starting $runName."
        $start = [Diagnostics.ProcessStartInfo]::new('dotnet')
        $start.WorkingDirectory = $manualRoot
        $start.UseShellExecute = $false
        $start.CreateNoWindow = $true
        $start.RedirectStandardOutput = $true
        $start.RedirectStandardError = $true
        foreach ($argument in @('StringExecutionRecovery.ChildHarness.dll','--benchmarkName','Marimo.Kotowari.Benchmarks.JsonStreamBenchmarks.StringInput','--benchmarkId','0')) {
            $start.ArgumentList.Add($argument)
        }
        $start.Environment['DOTNET_TieredPGO'] = '1'
        $utc = [DateTime]::UtcNow
        $watch = [Diagnostics.Stopwatch]::StartNew()
        $process = [Diagnostics.Process]::Start($start)
        if (-not $process) { throw "Could not start measurement process: $runName" }
        $processId = $process.Id
        try {
            $process.ProcessorAffinity = [IntPtr]4
            $affinity = $process.ProcessorAffinity.ToInt64()
            if ($affinity -ne 4) { throw "Affinity mismatch: $runName" }
            $stdoutTask = $process.StandardOutput.ReadToEndAsync()
            $stderrTask = $process.StandardError.ReadToEndAsync()
            while (-not $process.WaitForExit(1000)) {
                if ($watch.Elapsed.TotalSeconds -gt 180) { throw "Measurement timed out: $runName" }
            }
            $stdout = $stdoutTask.GetAwaiter().GetResult()
            $stderr = $stderrTask.GetAwaiter().GetResult()
            [IO.File]::WriteAllText($hostLog,$stdout,[Text.UTF8Encoding]::new($false))
            [IO.File]::WriteAllText($stderrPath,$stderr,[Text.UTF8Encoding]::new($false))
            if ($process.ExitCode -ne 0) { throw "Measurement process exited $($process.ExitCode): $runName" }
            if ($stderr.Trim().Length -ne 0) { throw "Unexpected stderr: $runName" }
            if ($stdout -notmatch '(?m)^// AfterAll\s*$') { throw "Missing completion signal: $runName" }
        } finally {
            if (-not $process.HasExited) { $process.Kill(); $process.WaitForExit() }
            $process.Dispose()
        }
        $elapsedSeconds = $watch.Elapsed.TotalSeconds
    }
    if ($stderr.Trim().Length -ne 0) { throw "Unexpected stderr: $runName" }
    if ($stdout -notmatch '(?m)^// AfterAll\s*$') { throw "Missing completion signal: $runName" }
    $afterHash = (Get-FileHash -LiteralPath $assembly -Algorithm SHA256).Hash
    if ($beforeHash -ne $afterHash) { throw "Built assembly changed during run: $runName" }
    foreach ($expectedDll in $expectedDlls) {
        $dllPath = Join-Path $manualRoot $expectedDll.Name
        if ((Get-FileHash -LiteralPath $dllPath -Algorithm SHA256).Hash -ne $expectedDll.SHA256) { throw "Frozen DLL hash mismatch after run: $variant/$($expectedDll.Name)" }
    }

    $observations = @([regex]::Matches($stdout, '(?m)^Workload(?<stage>Warmup|Actual|Result)\s+(?<index>\d+):\s+(?<ops>\d+) op, (?<ns>[\d.]+) ns, (?<display>[\d.]+) (?<unit>ns|us|μs|µs|ms|s)/op') | ForEach-Object {
        $displayValue = [double]::Parse($_.Groups['display'].Value,[Globalization.CultureInfo]::InvariantCulture)
        $displayMultiplier = switch ($_.Groups['unit'].Value) { 'ns' { 1.0 } 'us' { 1e3 } 'μs' { 1e3 } 'µs' { 1e3 } 'ms' { 1e6 } 's' { 1e9 } }
        [pscustomobject]@{
            Stage=$_.Groups['stage'].Value
            Iteration=[int]$_.Groups['index'].Value
            Operations=[int]$_.Groups['ops'].Value
            TotalNanoseconds=[double]::Parse($_.Groups['ns'].Value,[Globalization.CultureInfo]::InvariantCulture)
            DisplayNsPerOperation=$displayValue * $displayMultiplier
            DisplayRoundingToleranceNs=0.000055 * $displayMultiplier
        }
    })
    foreach ($stage in 'Warmup','Actual','Result') {
        $expected = if ($stage -eq 'Warmup') { 16 } else { 8 }
        $rows = @($observations | Where-Object Stage -eq $stage)
        if ($rows.Count -ne $expected -or @($rows | Where-Object Operations -ne 4).Count) { throw "Unexpected $stage observations or operation count: $runName" }
        if (@($rows | Where-Object { [math]::Abs(($_.TotalNanoseconds / $_.Operations) - $_.DisplayNsPerOperation) -gt $_.DisplayRoundingToleranceNs }).Count) { throw "Nanoseconds/Operations normalization mismatch: $runName" }
    }
    if ($stdout -notmatch '(?m)^// Job: .*OutlierMode=DontRemove.*Affinity=(?:0{0,61})100.*InvocationCount=4.*IterationCount=8.*LaunchCount=1.*UnrollFactor=1.*WarmupCount=16') { throw "Job settings mismatch: $runName" }

    $actuals = @($observations | Where-Object Stage -eq 'Actual')
    $results = @($observations | Where-Object Stage -eq 'Result')
    $actualValues = @($actuals | ForEach-Object { $_.TotalNanoseconds / $_.Operations })
    $resultValues = @($results | ForEach-Object { $_.TotalNanoseconds / $_.Operations })
    $resultMeanNs = ($resultValues | Measure-Object -Average).Average
    $actualMeanNs = ($actualValues | Measure-Object -Average).Average
    $displayMeanNs = (($results | ForEach-Object { $_.DisplayNsPerOperation } | Measure-Object -Average).Average)
    $displayMeanToleranceNs = (($results | ForEach-Object { $_.DisplayRoundingToleranceNs } | Measure-Object -Average).Average)
    if ([math]::Abs($resultMeanNs - $displayMeanNs) -gt $displayMeanToleranceNs) { throw "Result mean differs from displayed BDN mean beyond rounding: $runName" }
    $gc = [regex]::Match($stdout, '(?m)^// GC:\s+(?<gen0>\d+)\s+(?<gen1>\d+)\s+(?<gen2>\d+)\s+(?<allocated>\d+)\s+(?<operations>\d+)')
    if (-not $gc.Success -or [long]$gc.Groups['operations'].Value -ne 4) { throw "Missing or invalid allocation counters: $runName" }
    $runtime = [regex]::Match($stdout,'(?m)^// Runtime=(?<runtime>.+)$')
    $benchmarkDotNet = [regex]::Match($stdout,'(?m)^// BenchmarkDotNet v(?<version>\S+)')
    if (-not $runtime.Success -or -not $benchmarkDotNet.Success) { throw "Runtime or BenchmarkDotNet version missing: $runName" }

    $sourceFiles = @(Get-ChildItem -LiteralPath $sourceRoot -Recurse -File | Where-Object { ($_.Extension -in @('.cs','.csproj') -or $_.Name -eq '.editorconfig') -and $_.FullName -notmatch '[\\/](bin|obj)[\\/]' } | Sort-Object FullName | ForEach-Object {
        [ordered]@{ Path=$_.FullName.Substring($sourceRoot.Length+1).Replace('\','/'); SHA256=(Get-FileHash -LiteralPath $_.FullName -Algorithm SHA256).Hash }
    })
    $libraryPath = Join-Path $manualRoot 'Marimo.Kotowari.dll'
    $jsonPath = Join-Path $manualRoot 'Marimo.Parser.dll'
    $libraryHash = (Get-FileHash -LiteralPath $libraryPath -Algorithm SHA256).Hash
    $jsonHash = (Get-FileHash -LiteralPath $jsonPath -Algorithm SHA256).Hash
    $executedLibrary = Join-Path $manualRoot 'Marimo.Kotowari.dll'
    $executedJson = Join-Path $manualRoot 'Marimo.Parser.dll'
    if ((Get-FileHash -LiteralPath $executedLibrary -Algorithm SHA256).Hash -ne $libraryHash -or (Get-FileHash -LiteralPath $executedJson -Algorithm SHA256).Hash -ne $jsonHash) { throw "Manual harness DLL hashes differ from frozen inputs: $runName" }

    $record = [ordered]@{
        Run=$runName; Batch=$Batch; Variant=$variant; Method='StringInput'; MeanNs=$resultMeanNs
        ActualMeanNs=$actualMeanNs; ResultMeanNsPerOperation=$resultMeanNs; DisplayMeanNsPerOperation=$displayMeanNs
        ConsoleNormalizationVerified=$true; ResultObservationCount=$results.Count
        AllocatedBytesPerOperation=([long]$gc.Groups['allocated'].Value / [long]$gc.Groups['operations'].Value)
        GC=@([long]$gc.Groups['gen0'].Value,[long]$gc.Groups['gen1'].Value,[long]$gc.Groups['gen2'].Value)
        ActualIterations=@($actuals | ForEach-Object { [ordered]@{ BdnNanoseconds=$_.TotalNanoseconds; Operations=$_.Operations; NsPerOperation=($_.TotalNanoseconds/$_.Operations); DisplayNsPerOperation=$_.DisplayNsPerOperation } })
        ActualNsPerOperation=$actualValues
        ResultIterations=@($results | ForEach-Object { [ordered]@{ BdnNanoseconds=$_.TotalNanoseconds; Operations=$_.Operations; NsPerOperation=($_.TotalNanoseconds/$_.Operations); DisplayNsPerOperation=$_.DisplayNsPerOperation } })
        ActualCount=$actuals.Count; ResultCount=$results.Count; WarmupCount=16
        Runtime=$runtime.Groups['runtime'].Value; BenchmarkDotNet=$benchmarkDotNet.Groups['version'].Value
        Job=([regex]::Match($stdout,'(?m)^// Job: (?<job>.+)$').Groups['job'].Value); TieredPGO=1; Affinity=$affinity
        ProcessId=$processId; StartUTC=$utc.ToString('o'); WallSeconds=$elapsedSeconds
        PowerShell=$PSVersionTable.PSVersion.ToString()
        ResumedExistingOutput=$reuseOutput
        InputBytes=(Get-Item -LiteralPath $inputPath).Length; InputSHA256=$expectedInputHash
        AssemblySHA256=$afterHash; MeasurementHostAssemblySHA256=(Get-FileHash -LiteralPath $measurementHost -Algorithm SHA256).Hash
        LibraryDLLSHA256=$libraryHash; JsonDLLSHA256=$jsonHash
        ChildLibraryDLLSHA256=$libraryHash; ChildJsonDLLSHA256=$jsonHash
        DLLManifestSHA256=(Get-FileHash -LiteralPath $manifestPath -Algorithm SHA256).Hash
        SourceFiles=$sourceFiles
    }
    $record | ConvertTo-Json -Depth 8 | Set-Content -LiteralPath $summaryPath -Encoding utf8
    Write-Output ('Completed {0}: mean {1:F3} ms, {2} Actual/{3} Result.' -f $runName,($record.MeanNs/1e6),$record.ActualCount,$record.ResultCount)
}
Write-Output "Block $Block completed."

